promql:
topk(3, sum by (pod) (
  container_network_receive_packets_dropped_total{interface="eth0", namespace="obs", node="k8s-node2"} - ignoring (pod) group_left
  container_network_receive_packets_total{interface="eth0", namespace="obs", node="k8s-node2"}
) / rate(container_network_receive_packets_total{interface="eth0", namespace="obs", node="k8s-node2"}[5m]))

(
  sum by (pod)(
    container_fs_usage_bytes{pod=~"news.*", node=~"k8s-node1|k8s-node4"}
  )
  /
  sum by (node)(
    node_filesystem_size_bytes{node=~"k8s-node1|k8s-node4"}
  )
)
